 1→import { createRoot } from "react-dom/client";
 2→import App from "./App.tsx";
 3→import "./index.css";
 4→import { logClientError } from "./lib/logClientError";
 5→import AppErrorBoundary from "./components/AppErrorBoundary";
 6→
 7→// Global uncaught JS errors
 8→window.onerror = (message, source, lineno, colno, error) => {
 9→  const src = source
10→    ? new URL(source, window.location.href).pathname.split("/").pop() ?? "frontend"
11→    : "frontend";
12→  logClientError(
13→    "UnhandledError",
14→    src,
15→    String(message),
16→    error?.stack,
17→    { source, lineno, colno },
18→  );
19→};
20→
21→// Global unhandled promise rejections
22→window.addEventListener("unhandledrejection", (event) => {
23→  const reason = event.reason;
24→  const message = reason instanceof Error ? reason.message : String(reason ?? "Unhandled rejection");
25→  const stack = reason instanceof Error ? reason.stack : undefined;
26→  logClientError("UnhandledRejection", "frontend", message, stack);
27→});
28→
29→createRoot(document.getElementById("root")!).render(
30→  <AppErrorBoundary>
31→    <App />
32→  </AppErrorBoundary>,
33→);
